ok = 0
for f, s in checks:
    t = open(os.path.join(d, f), encoding="utf-8").read()
    t1 = re.sub(r"\s+", " ", t)
    hit = re.sub(r"\s+", " ", s) in t1
    ok += hit
    print("OK  " if hit else "MISS", f, "|", s[:90])
print(ok, "of", len(checks), "excerpts found verbatim")
